<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { api } from '../services/api';
import type { Badge, MunicipalSettings } from '../types';
import { municipalSettings } from '../services/municipalSettings';
import ConfirmDialog from './ConfirmDialog.vue';
const settings = ref<MunicipalSettings>({ map: { latitude: 14.5995, longitude: 120.9842, zoom: 13 }, hotlines: [] });
const badges = ref<Badge[]>([]); const error = ref(''); const saved = ref(''); const busy = ref(false); const pending = ref<'settings' | number | null>(null);
const loading = ref(true); const ready = ref(false);
async function load() {
  loading.value = true; error.value = '';
  try {
    const [nextSettings, nextBadges] = await Promise.all([api<MunicipalSettings>('/api/settings'), api<Badge[]>('/api/badges')]);
    settings.value = nextSettings; badges.value = nextBadges; ready.value = true;
  } catch (e) { error.value = (e as Error).message; }
  finally { loading.value = false; }
}
onMounted(load);
async function save() { busy.value = true; error.value = ''; try { if (pending.value === 'settings') { settings.value = await api<MunicipalSettings>('/api/admin/settings', { method: 'PUT', body: JSON.stringify(settings.value) }); municipalSettings.value = settings.value; saved.value = 'Map and hotlines saved.'; } else if (typeof pending.value === 'number') { const badge = badges.value.find(b => b.id === pending.value)!; const updated = await api<Badge>(`/api/admin/badges/${badge.id}`, { method: 'PATCH', body: JSON.stringify(badge) }); badges.value = badges.value.map(b => b.id === updated.id ? updated : b); saved.value = `${updated.name} badge saved.`; } pending.value = null; } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
</script>
<template><p v-if="loading" role="status">Loading municipal settings...</p><div v-else-if="ready" class="cms-grid"><section class="cms-card"><h2>Municipal map & emergency hotlines</h2><p class="field-help">The map opens at this location when no report is selected. Publish approved emergency numbers only.</p><form class="form-body" @submit.prevent="pending = 'settings'"><div class="form-grid"><label>Default latitude<input v-model.number="settings.map.latitude" type="number" step="any" min="-90" max="90" required></label><label>Default longitude<input v-model.number="settings.map.longitude" type="number" step="any" min="-180" max="180" required></label></div><label>Default zoom<input v-model.number="settings.map.zoom" type="number" step="any" min="3" max="19" required></label><h3>Emergency hotlines</h3><div v-for="(line, index) in settings.hotlines" :key="index" class="hotline-edit"><label>Service<input v-model="line.name" required minlength="2" maxlength="80" placeholder="Municipal disaster office"></label><label>Phone number<input v-model="line.number" required maxlength="30" pattern="[+0-9\(\) \-]+" placeholder="Phone number"></label><button class="text-button" type="button" @click="settings.hotlines.splice(index, 1)">Remove</button></div><button class="button secondary" type="button" :disabled="settings.hotlines.length >= 20" @click="settings.hotlines.push({ name: '', number: '' })">Add hotline</button><button class="button primary" type="submit">Save map and hotlines</button></form></section>
<section class="cms-card"><h2>Achievement badges & rewards</h2><p class="field-help">Milestones use verified reports. Cash and gifts shown here are informational; fulfillment is handled by the municipality.</p><div v-for="badge in badges" :key="badge.id" class="badge-editor form-body"><span class="achievement-badge" :class="badge.color">{{ badge.name }} · {{ badge.threshold.toLocaleString() }}</span><label>Badge name<input v-model="badge.name" maxlength="80" required></label><label>Description<textarea v-model="badge.description" maxlength="1000" rows="2" required></textarea></label><label>Reward<select v-model="badge.reward_type"><option value="none">No reward</option><option value="cash">Cash bonus</option><option value="gift">Gift</option></select></label><label v-if="badge.reward_type === 'cash'">Cash amount (PHP)<input v-model.number="badge.cash_amount" type="number" min="0" max="1000000" step="0.01" required></label><label v-if="badge.reward_type === 'gift'">Gift description<input v-model="badge.reward_description" maxlength="255" required></label><button class="button secondary" @click="pending = badge.id">Save {{ badge.name }}</button></div></section></div><p v-if="error" class="form-error" role="alert">{{ error }}</p><button v-if="!ready && !loading" class="button secondary" @click="load">Retry loading settings</button><p v-if="saved" class="notice success" role="status">{{ saved }}</p><ConfirmDialog v-if="pending !== null" title="Publish CMS changes?" message="These changes will be visible in the citizen app immediately." :busy="busy" confirm-label="Publish changes" @close="pending = null" @confirm="save" /></template>
